(function(root){'use strict';
const t=(en,es)=>({en,es}),VERSION='ac01-projects-1';
const text=(id,en,es)=>({id,label:t(en,es),type:'text'});
const choose=(id,en,es,options)=>({id,label:t(en,es),type:'select',options});
const option=(value,en,es)=>({value,label:t(en,es)});
const reason=text('reason','Explain the comparisons or evidence behind your answer. Uncertainty is welcome.','Explica las comparaciones o pruebas que sustentan tu respuesta. Puedes expresar dudas.');
const prediction=()=>[choose('choice','Your first choice','Tu primera elección',[option('first','First option','Primera opción'),option('second','Second option','Segunda opción'),option('other','Another plan / unsure','Otro plan / no sé')]),reason];
const strategies=(labels)=>[
 ...['A0','A1','B0','B1'].map((id,i)=>choose(id,(i<2?'A':'B')+': best response when the other chooses '+labels[i%2].en,(i<2?'A':'B')+': mejor respuesta cuando la otra parte elige '+labels[i%2].es,[option('0',labels[0].en,labels[0].es),option('1',labels[1].en,labels[1].es),option('both','Both tie','Ambas empatan')])),
 choose('dominance','Which option is strictly dominant for both players?','¿Qué opción es estrictamente dominante para ambos jugadores?',[option('0',labels[0].en,labels[0].es),option('1',labels[1].en,labels[1].es),option('none','Neither','Ninguna')]),
 {id:'ne',type:'ne',label:t('Select ALL pure Nash equilibria, or select “none”. A tie is not a profitable deviation.','Selecciona TODOS los equilibrios de Nash puros, o «ninguno». Un empate no es una desviación rentable.')},reason];
const NS=[t('N · North entrance','N · Entrada norte'),t('S · Sports field','S · Cancha')],CD=[t('C · Complete','C · Completar'),t('D · Skip','D · Omitir')];
const matrixStep=(id,title,body,model)=>({id,title,body,model,matrix:true,fields:[text('calculation','Show at least one payoff calculation.','Muestra al menos un cálculo de pagos.')],hint:t('Separate the shared benefit or demand from each player’s own costs. Every cell records A first, then B.','Separa la demanda o el beneficio compartido de los costos de cada jugador. Cada casilla registra primero A y luego B.')});
const analyze=(id,title,body,model,labels)=>({id,title,body,model,fields:strategies(labels),hint:t('Hold the other player’s choice fixed. Compare only your own payoff. Repeat for both players and every proposed equilibrium.','Mantén fija la elección de la otra parte. Compara solo tu propio pago. Repite para ambos jugadores y cada equilibrio propuesto.')});
const ACTIVITIES=[{
 id:'food-trucks',title:t('Food trucks at the school fair','Puestos de comida en la feria escolar'),kind:t('Project · 25–35 minutes','Proyecto · 25–35 minutos'),intro:t('Where should you park when another truck is choosing too? Build a model, test a change in demand, and advise the organizer.','¿Dónde conviene estacionarte si otro puesto también está decidiendo? Construye un modelo, cambia la demanda y asesora a quien organiza.'),labels:NS,
 story:t('Two food trucks, A and B, simultaneously choose N (north entrance) or S (sports field). North has 120 customers; south has 80. Each buys one meal. A truck alone serves everyone in its area; two trucks in one area split customers equally. Capacity is sufficient, trucks are equally appealing, and customers do not move between areas. Demand in an empty area is lost. Each meal contributes USD 5 after variable costs. Each truck then pays its own fixed USD 100 cost once. Profit = meals × USD 5 − USD 100. These are simplified assumptions, not observed school data.','Dos puestos, A y B, eligen simultáneamente N (entrada norte) o S (cancha). Hay 120 clientes al norte y 80 al sur; cada uno compra una comida. Un puesto solo atiende a todos en su zona; dos en la misma zona se reparten los clientes por igual. Hay capacidad suficiente, ambos atraen igual y los clientes no cambian de zona. Se pierde la demanda de una zona vacía. Cada comida aporta USD 5 después de los costos variables. Cada puesto paga una vez su costo fijo de USD 100. Ganancia = comidas × USD 5 − USD 100. Son supuestos simplificados, no datos observados de una escuela.'),
 steps:[
 {id:'predict',title:t('01 · Choose before calculating','01 · Elige antes de calcular'),body:t('First option: N. Second option: S. Where would you choose? What do you expect B to do, and why?','Primera opción: N. Segunda opción: S. ¿Qué elegirías? ¿Qué esperas que haga B y por qué?'),fields:prediction()},
 matrixStep('baseline',t('02 · Build the payoff table','02 · Construye la tabla de pagos'),t('Calculate all eight profits in USD. Remember to split demand when both trucks choose the same area.','Calcula las ocho ganancias en USD. Recuerda dividir la demanda cuando ambos puestos eligen la misma zona.'),'trucks80'),
 analyze('strategy',t('03 · Can one truck improve alone?','03 · ¿Puede mejorar un solo puesto?'),t('Use the original demand: north 120, south 80. Explain why staying or switching is a best response, and check every equilibrium. Maximizing total profit is a different question.','Usa la demanda original: norte 120, sur 80. Explica por qué quedarse o cambiar es una mejor respuesta y comprueba cada equilibrio. Maximizar la ganancia total es otra pregunta.'),'trucks80',NS),
 {...matrixStep('change',t('04 · South demand falls to 50','04 · La demanda del sur baja a 50'),t('Only south demand changes, from 80 to 50. Recalculate. Does either truck now have a strictly dominant choice? Find all equilibria and explain a unilateral deviation from a split location.','Solo cambia la demanda del sur, de 80 a 50. Vuelve a calcular. ¿Existe ahora una opción estrictamente dominante? Encuentra todos los equilibrios y explica una desviación unilateral desde ubicaciones separadas.'),'trucks50'),fields:[...strategies(NS)]},
 {id:'recommend',title:t('05 · Two different recommendations','05 · Dos recomendaciones distintas'),body:t('Advise truck A and the organizer separately. State your assumptions, information to collect, and what would make you reconsider. With south demand 50, compare total truck profit at NN and split locations. That total does not measure customers’ welfare. An allocation rule changes the game; saying “cooperate” does not enforce it.','Asesora por separado al puesto A y a quien organiza. Indica tus supuestos, qué información falta y qué te haría reconsiderar. Con demanda sur de 50, compara la ganancia total de los puestos en NN y separados. Ese total no mide el bienestar de los clientes. Una regla de asignación cambia el juego; decir «cooperen» no la hace cumplir.'),fields:[text('truck','Recommendation to A: I recommend… because… assuming… I would reconsider if…','Recomendación a A: recomiendo… porque… suponiendo… reconsideraría si…'),text('organizer','Recommendation to the organizer, including implementation and missing information','Recomendación a quien organiza, incluida su aplicación y la información faltante')]},
 {...analyze('boundary',t('06 · Optional boundary: south has 60','06 · Extensión opcional: 60 al sur'),t('Find all equilibria when south demand is exactly 60. Explain the difference between weak and strict dominance. You may leave this extension unfinished.','Encuentra todos los equilibrios cuando la demanda sur es exactamente 60. Explica la diferencia entre dominancia débil y estricta. Puedes dejar esta extensión sin terminar.'),'trucks60',NS),optional:true}
 ]
},{
 id:'shared-printer',title:t('Who maintains the shared printer?','¿Quién mantiene la impresora compartida?'),kind:t('Project · 30–40 minutes','Proyecto · 30–40 minutos'),intro:t('Two clubs share a 3D printer. Compare a deduction with a practical way to reduce maintenance costs.','Dos clubes comparten una impresora 3D. Compara una deducción con una forma práctica de reducir el costo del mantenimiento.'),labels:CD,
 story:t('Robotics club A and design club B each have a different maintenance checklist. They simultaneously choose Complete (C) or Skip (D). If both complete, each receives benefit 10; if only one completes, each receives 6; if neither completes, each receives 3. Completing costs that club 5; skipping costs 0. Payoff = benefit − own cost. These are invented utility points, not money, grades, or measured happiness. Higher points are preferred.','El club de robótica A y el de diseño B tienen listas distintas de mantenimiento. Eligen simultáneamente Completar (C) u Omitir (D). Si ambos completan, cada uno recibe un beneficio de 10; si solo uno completa, cada uno recibe 6; si ninguno completa, cada uno recibe 3. Completar cuesta 5 al club que lo hace; omitir cuesta 0. Pago = beneficio − costo propio. Son puntos de utilidad inventados, no dinero, calificaciones ni felicidad medida. Se prefieren más puntos.'),
 steps:[
 {id:'predict',title:t('01 · What would your club do?','01 · ¿Qué haría tu club?'),body:t('First option: complete. Second option: skip. Predict your choice and the other club’s choice before seeing a solution.','Primera opción: completar. Segunda opción: omitir. Predice tu elección y la del otro club antes de ver una solución.'),fields:prediction()},
 matrixStep('baseline',t('02 · Benefit minus own cost','02 · Beneficio menos costo propio'),t('Calculate each payoff. When neither club completes, each still receives benefit 3.','Calcula cada pago. Si ningún club completa, cada uno aún recibe un beneficio de 3.'),'printer0'),
 analyze('strategy',t('03 · A shared difficulty','03 · Una dificultad compartida'),t('Compare best responses and all equilibria. Explain how both can prefer CC while each has an incentive to skip.','Compara mejores respuestas y todos los equilibrios. Explica cómo ambos pueden preferir CC aunque cada uno tenga un incentivo para omitir.'),'printer0',CD),
 {...matrixStep('fee15',t('04 · A deduction of 1.5 points','04 · Una deducción de 1,5 puntos'),t('Every club that skips certainly loses f = 1.5 additional points. The deduction is not transferred to the other club. All benefits and costs stay the same. Recalculate and find ALL equilibria.','Cada club que omite pierde con certeza f = 1,5 puntos adicionales. La deducción no se transfiere al otro club. Los beneficios y costos no cambian. Vuelve a calcular y encuentra TODOS los equilibrios.'),'printer15'),fields:strategies(CD)},
 {...matrixStep('fee3',t('05 · A deduction of 3 points','05 · Una deducción de 3 puntos'),t('Now the certainly enforced deduction is f = 3. Recalculate and compare with f = 0 and f = 1.5. Does every positive deduction guarantee cooperation?','Ahora la deducción aplicada con certeza es f = 3. Vuelve a calcular y compara con f = 0 y f = 1,5. ¿Toda deducción positiva garantiza cooperación?'),'printer3'),fields:strategies(CD)},
 {...matrixStep('training',t('06 · An alternative: easier maintenance','06 · Alternativa: mantenimiento más sencillo'),t('Remove all deductions. Suppose training and tools reduce each checklist’s cost from 5 to 2 without changing benefits. Find the new payoffs and equilibria. This cost reduction is an assumption to investigate, not a proven result.','Elimina las deducciones. Supón que capacitación y herramientas reducen el costo de cada lista de 5 a 2 sin cambiar los beneficios. Encuentra los pagos y equilibrios. La reducción de costo es un supuesto por investigar, no un resultado demostrado.'),'printerTraining'),fields:strategies(CD)},
 {id:'proposal',title:t('07 · Recommend a workable rule','07 · Recomienda una regla viable'),body:t('Compare no rule, deductions, and training. Account for monitoring, enforcement, fairness, upfront training cost and whether the assumed cost reduction is realistic. Explain what evidence could change your proposal. Repeated contact alone does not guarantee cooperation.','Compara no imponer reglas, aplicar deducciones y capacitar. Considera supervisión, cumplimiento, equidad, costo inicial de capacitación y si es realista reducir el costo. Explica qué pruebas cambiarían tu propuesta. El contacto repetido por sí solo no garantiza cooperación.'),fields:[text('proposal','Proposal, supporting payoff comparisons, implementation and limitations','Propuesta, comparaciones de pagos, aplicación y limitaciones')]},
 {id:'boundary',title:t('08 · Optional: uncertain enforcement','08 · Extensión opcional: cumplimiento incierto'),body:t('For any f ≥ 0, when is CC an equilibrium? When is DD? Check the ties at f = 1 and f = 2. Next suppose a 3-point deduction detects skipping with probability q = 0.5, never punishes completion, and clubs maximize expected points. Compare with certain f = 1.5. What q makes C strictly dominant?','Para cualquier f ≥ 0, ¿cuándo es CC un equilibrio? ¿Y DD? Comprueba los empates en f = 1 y f = 2. Luego supone que una deducción de 3 puntos detecta una omisión con probabilidad q = 0,5, nunca castiga completar y los clubes maximizan puntos esperados. Compara con f = 1,5 seguro. ¿Qué q hace a C estrictamente dominante?'),fields:[reason],optional:true,
 solution:t('CC is an equilibrium iff f ≥ 1; DD iff f ≤ 2. Both exist for 1 ≤ f ≤ 2. C is strictly dominant only when f > 2. Under the stated expected-points assumptions the effective deduction is 3q: at q = 0.5 both CC and DD remain equilibria; strict dominance needs q > 2/3. At q = 2/3 there is a tie and both remain.','CC es equilibrio si y solo si f ≥ 1; DD si y solo si f ≤ 2. Ambos existen para 1 ≤ f ≤ 2. C es estrictamente dominante solo si f > 2. Bajo los supuestos de puntos esperados, la deducción efectiva es 3q: con q = 0,5 siguen existiendo CC y DD; la dominancia estricta necesita q > 2/3. En q = 2/3 hay empate y permanecen ambos.')}
 ]
},{
 id:'missed-deadline',title:t('When a teammate misses a deadline','Cuando alguien del equipo no cumple un plazo'),kind:t('Case study · 20–30 minutes','Estudio de caso · 20–30 minutos'),intro:t('Separate facts from assumptions, respond to new evidence, and write a conditional plan with credible limits.','Separa hechos de supuestos, responde a nueva información y escribe un plan condicional con límites creíbles.'),
 story:t('Wednesday, 18:00. Your group’s data poster is due Friday at 15:00. You handle data, Kai makes graphs, and Mina handles layout and presentation. There is a shared project grade and no clear individual contribution policy. Kai promised a first graph by Wednesday 17:00. No file has arrived. At 16:30 Kai wrote, “I’ll work on it later.” You do not know why. You and Mina still have your own work to finish. This is a fictional case; do not enter real classmates’ private details.','Miércoles, 18:00. El cartel de datos del equipo se entrega el viernes a las 15:00. Tú preparas los datos, Kai las gráficas y Mina el diseño y la presentación. Hay una calificación compartida y no está clara la política sobre contribuciones individuales. Kai prometió una primera gráfica para el miércoles a las 17:00. No llegó ningún archivo. A las 16:30 escribió: «Lo haré después». No sabes por qué. Tú y Mina aún tienen trabajo propio pendiente. El caso es ficticio; no ingreses datos privados de compañeros reales.'),
 steps:[
 {id:'initial',title:t('01 · Your decision with limited information','01 · Tu decisión con información limitada'),body:t('You may combine actions: do some of Kai’s work, agree on a verifiable checkpoint, redistribute tasks, or ask the teacher for help. What would you do now, and why? Save this initial decision before reading new information.','Puedes combinar acciones: hacer parte del trabajo de Kai, acordar un punto de control verificable, repartir tareas o pedir apoyo docente. ¿Qué harías ahora y por qué? Guarda esta decisión antes de leer información nueva.'),fields:[text('plan','Initial action and reasons','Acción inicial y razones')]},
 {id:'evidence',title:t('02 · What do you actually know?','02 · ¿Qué sabes realmente?'),body:t('Distinguish evidence from motive. If Kai expects you to finish everything, how might that affect incentives? Treat this as a hypothesis, not a fact. A request to the teacher is allowed; you cannot unilaterally change grades or remove a teammate.','Distingue pruebas de motivos. Si Kai espera que termines todo, ¿cómo podría afectar sus incentivos? Trátalo como hipótesis, no como hecho. Puedes pedir ayuda docente; no puedes cambiar calificaciones ni expulsar a alguien por tu cuenta.'),fields:[text('facts','List three known facts and two assumptions separately','Enumera por separado tres hechos conocidos y dos supuestos'),text('alternatives','Give two possible explanations and information that would distinguish them','Da dos explicaciones posibles e información que permitiría distinguirlas'),text('message','Draft a message asking about progress, obstacles and a small deliverable with a deadline','Redacta un mensaje sobre avance, obstáculos y una entrega pequeña con plazo'),text('limits','How much help, until when, and what fallback? Explain the possible incentive effect.','¿Cuánta ayuda, hasta cuándo y con qué alternativa? Explica el posible efecto en los incentivos.')]},
 {id:'branchA',title:t('03 · Branch A: a skill obstacle','03 · Rama A: dificultad de conocimientos'),body:t('Independent branch A: Kai has cleaned the data but does not know which graph would compare it or how to label axes. Kai has one hour available Thursday. Keep or revise your initial plan. Consider a brief demonstration, a small sketch, or repartitioning. What independently completed next step would you verify?','Rama independiente A: Kai limpió los datos, pero no sabe qué gráfica sirve para compararlos ni cómo rotular ejes. Tiene una hora disponible el jueves. Mantén o modifica tu plan inicial. Considera una demostración breve, un boceto o redistribuir tareas. ¿Qué siguiente paso realizado de forma independiente verificarías?'),fields:[text('revision','What stays, what changes, and which new evidence explains your decision?','¿Qué mantienes, qué cambias y qué información nueva explica tu decisión?'),text('checkpoint','Concrete task, check time, evidence of progress and fallback','Tarea concreta, hora de revisión, prueba de avance y alternativa')]},
 {id:'transfer',title:t('04 · Transfer: choose a different branch','04 · Transferencia: elige otra rama'),body:t('B and C are independent alternatives to A, not later events in the same story. Choose at least one. You can submit one, switch branches, and submit the other; both versions remain in your history.','B y C son alternativas independientes a A, no eventos posteriores de la misma historia. Elige al menos una. Puedes enviar una, cambiar de rama y enviar la otra; ambas versiones quedan en el historial.'),fields:[choose('branch','Independent branch','Rama independiente',[option('B','B · Skill and time are available','B · Tiene conocimientos y tiempo'),option('C','C · Still unreachable Thursday','C · Sigue sin responder el jueves')]),text('revision','Keep or revise your plan: cite the new evidence, action, checkpoint and fallback','Mantén o modifica tu plan: cita la nueva información, acción, punto de control y alternativa')],branches:{B:t('Kai can do the task and has time, but says other work takes priority because Kai expects you to finish this project. Set responsibilities, bounded help and credible checkpoints; do not invent authority you do not have.','Kai sabe hacer la tarea y tiene tiempo, pero dice que prioriza otro trabajo porque espera que termines este proyecto. Define responsabilidades, ayuda limitada y puntos de control creíbles; no inventes autoridad que no tienes.'),C:t('It is now Thursday 16:00. Kai remains unreachable and there is no file; the reason is still unknown. Plan a minimum viable submission, record observable facts, set a stopping point, and ask the teacher for support if needed.','Son las 16:00 del jueves. Kai sigue sin responder y no hay archivo; aún se desconoce el motivo. Planea una entrega mínima viable, registra hechos observables, fija un límite y pide apoyo docente si hace falta.')}},
 {id:'final',title:t('05 · A conditional action plan','05 · Un plan de acción condicional'),body:t('Write at least two usable “if… then…” rows. Each should name a condition, action, observable output, check time and fallback. Review assumptions, strategic reasoning, use of evidence, and feasibility. These dimensions support self or teacher review; no essay score or personality label is generated.','Escribe al menos dos filas útiles de «si… entonces…». Cada una debe indicar condición, acción, resultado observable, hora de revisión y alternativa. Revisa supuestos, razonamiento estratégico, uso de pruebas y viabilidad. Estas dimensiones apoyan la revisión propia o docente; no se genera una nota del texto ni una etiqueta personal.'),fields:[text('row1','Plan row 1: condition → action → output → check time → fallback','Fila 1: condición → acción → resultado → hora de revisión → alternativa'),text('row2','Plan row 2: condition → action → output → check time → fallback','Fila 2: condición → acción → resultado → hora de revisión → alternativa'),text('review','Self-review: which parts have clear support, partial support or need more detail? What would you ask a teacher to review?','Autoevaluación: ¿qué partes tienen apoyo claro, parcial o necesitan más detalle? ¿Qué pedirías revisar a un docente?')],solution:t('One possible response asks about the obstacle, agrees on a small graph with axes and units by Thursday noon, limits help, and names a fallback. Branch A can justify a brief demonstration; B can justify firmer verifiable responsibilities; C can justify a smaller submission and a factual request for teacher support. Other plans can be defensible. Explain evidence, constraints and tradeoffs; do not infer laziness from a missing file.','Una respuesta posible pregunta por el obstáculo, acuerda una gráfica pequeña con ejes y unidades para el jueves al mediodía, limita la ayuda y define una alternativa. A puede justificar una demostración breve; B, responsabilidades verificables más firmes; C, una entrega reducida y una solicitud objetiva de apoyo docente. Otros planes pueden ser defendibles. Explica pruebas, restricciones y costos; no deduzcas pereza de un archivo ausente.')}
 ]
}];
const api={VERSION,ACTIVITIES};if(typeof module==='object'&&module.exports)module.exports=api;else root.QuidenceGameProjectsContent=api;
})(typeof window==='undefined'?globalThis:window);
